(() => { const app = window.__CITY_APP, C = window.CITY, t = C.worldFromLatLon(43.6447, -79.399);
const n = C.nearestRoads(t.x, t.z, 80).find((r) => r.road.name === 'King Street West'); const p = n.road.pts; let ux = 1, uz = 0;
for (let i = 0; i + 1 < p.length; i++) { const L = Math.hypot(p[i + 1].x - p[i].x, p[i + 1].z - p[i].z); if (Math.hypot(p[i].x - n.px, p[i].z - n.pz) < L + 1) { ux = (p[i + 1].x - p[i].x) / L; uz = (p[i + 1].z - p[i].z) / L; } }
if (ux < 0) { ux = -ux; uz = -uz; }
app.teleportTo(n.px, n.pz, 0); app.cameraSystem.cinema = () => ({ pos: [n.px - ux * 60, 32, n.pz - uz * 60], look: [n.px + ux * 380, 0, n.pz + uz * 380], fov: 50 }); })()

